import json, pathlib, sys
stages=pathlib.Path(sys.argv[1]);raw=pathlib.Path(sys.argv[2]);values=[1000,1080,1090,1100,1110,1120,1200,1400];rows=[]
for focus in values:
 s=json.loads((stages/f'{focus}.json').read_text());r=json.loads((raw/f'{focus}.json').read_text());p=s['p']['points'][0];sp=s['measurements'][0];rp=r['measurements'][0]
 assert s['p']['frameId']==s['screenshotFrameId']==s['p']['completion']['frameId']
 assert s['state']['camera']==r['state']['camera'] and s['state']['renderQuality']==r['state']['renderQuality']
 rows.append({'focusMm':focus,'stageFrameId':s['p']['frameId'],'rawFrameId':r['result']['frameId'],'worldM':p['worldM'],'uv':p['sourceUv'],'sceneTexel':p['scene']['coordinate'],'depth':p['depth']['depth'],'signedCocMm':p['coc']['rgba'][0],'canonicalSignedCocMm':s['features'][0]['footprint']['signedCoCDiameterMm'],'majorRadiusMm':p['coc']['rgba'][1],'sceneLinearR':p['scene']['rgba'][0],'farLinearR':p['far']['rgba'][0],'nearLinearR':p['near']['rgba'][0],'nearAlpha':p['near']['rgba'][3],'compositeLinearR':p['composite']['rgba'][0], 'processedEdgeWidthCssPx':sp['measurement'].get('width10to90Px'),'rawEdgeWidthCssPx':rp['measurement'].get('width10to90Px'),'processedValid':sp['measurement']['valid'],'rawValid':rp['measurement']['valid']})
print(json.dumps({'fixture':'known near-edge, 1.1 m; target is not original room geometry','rows':rows,'interpretation':['Reprojected nearest scene texel changes between 1080 and 1090 mm, where the sampled scene color and both Raw and Processed edge widths also change. This is an upstream pixel-sampling observation for the fixture, not proof of the user-reported room behavior.','CoC is observed smooth through the sampled crossing; near alpha switches at the sign crossing, while near and far center colors agree in this specific state. This does not prove all occlusion/coverage transitions are continuous.','Edge widths are display-space 10–90% estimates with different Raw/Processed presentation; they are not a calibrated physical CoC transfer.'], 'limitations':['Per-point samples are nearest texels after reprojection and can change due pixel phase; no claim that different states should have identical texel values.','Raw and Processed are different browser runs with identical recorded canonical camera states and same hardware; they cannot be simultaneous frames.','The fixture is not the original photorealistic room.']},indent=2))
